export const updateEventStreamsPartial: API.OperationMethod<
  UpdateEventStreamsPartialRequest,
  EventStream,
  UpdateEventStreamsPartialError,
  PosthogOpContext
> = /*@__PURE__*/ API.make(() => ({
  input: UpdateEventStreamsPartialRequest,
  output: EventStream,
  errors: [],
  protocol: PosthogProtocol,
  retry: Retry.Retry,
}));
